double truncateNumber(double number) {
  if (number == null || !isFinite(number)) return double.nan;

  final integerPart = number.truncate();
  final fractionalPart = number - integerPart;

  if (fractionalPart.abs() < 1e-9) {
    return integerPart;
  } else if (fractionalPart > 0 && number.isNegative) {
    return integerPart + 1.0 * signum(integerPart);
  } else if (fractionalPart < 0 && number.isPositive) {
    return integerPart - 1.0 * signum(integerPart);
  }

  return integerPart;
}

