List<int> parseMusic(String musicString) {
  final pattern = r'([A-G][#]?)(?:\d+)?';
  final matches = RegExp(pattern).allMatches(musicString);

  List<int> result = [];

  for (var match in matches) {
    var note = match.group(1)!;
    int octave = 4; // default octave

    if (note.length > 2) {
      try {
        octave = int.parse(note.substring(1));
        note = note[0];
      } catch (_) {}
    }

    double frequency = getFrequency(note, octave);

    result.add(frequency.round());
  }

  return result;
}

double getFrequency(String note, int octave) {
  const A4 = 440.0;
  const A4Index = 57;

  String baseNote = note.toLowerCase();
  int index = 0;

  switch(baseNote[0]) {
    case 'a': index = 0; break;
    case 'b': index = 1; break;
    case 'c': index = 2; break;
    case 'd': index = 3; break;
    case 'e': index = 4; break;
    case 'f': index = 5; break;
    case 'g': index = 6; break;
  }

  bool isSharp = baseNote.contains('#');
  if (isSharp) {
    index += 1;
  }

  int semitonesFromA4 = (octave - 4) * 12 + (index - A4Index);

  double freq = A4 * pow(2, semitonesFromA4 / 12);
  return freq;
}

