List<int> sortThird(List<int> l) {
  List<int> result = List.from(l);

  // Extract elements at indices divisible by 3
  List<int> thirdElements = [];
  for (int i = 0; i < result.length; i += 3) {
    thirdElements.add(result[i]);
  }

  // Sort them
  thirdElements.sort();

  // Put them back
  int thirdIndex = 0;
  for (int i = 0; i < result.length; i += 3) {
    result[i] = thirdElements[thirdIndex];
    thirdIndex++;
  }

  return result;
}

