List<int> maximum(List<int> arr, int k) {
  if (k == 0 || arr.isEmpty) return [];

  final result = <int>[];
  final n = arr.length;
  final windowSize = min(k, n);

  // Create a max-heap to keep track of the top elements
  final heap = List<int>.filled(windowSize, 0);
  for (var i = 0; i < windowSize; i++) {
    heap[i] = arr[i];
  }

  _buildHeap(heap, windowSize); // Build initial max-heap

  result.add(heap[0]);

  for (var i = windowSize; i < n; i++) {
    // Remove the element going out of the window
    var indexToRemove = -1;
    for (var j = 0; j < windowSize; j++) {
      if (arr[i - windowSize] == heap[j]) {
        indexToRemove = j;
        break;
      }
    }

    // If the removed element is not the root, replace it and re-heapify
    if (indexToRemove != -1 && indexToRemove != 0) {
      heap[indexToRemove] = arr[i];
      _siftDown(heap, indexToRemove, windowSize);
    } else {
      heap[0] = arr[i]; // Otherwise, just add new element at root
    }

    _siftUp(heap, 0, windowSize);

    result.add(heap[0]); // Add current max to result
  }

  return result;
}

void _buildHeap(List<int> array, int size) {
  for (var i = floor((size - 1)/2); i >= 0; i--) {
    _siftDown(array, i, size);
  }
