void _siftDown(List<int> array, int i, int size) {
  while (true) {
    var leftChildIndex = 2 * i + 1;
    var rightChildIndex = 2 * i + 2;
    var smallestIndex = i;

    if (leftChildIndex < size && array[leftChildIndex] > array[smallestIndex]) {
      smallestIndex = leftChildIndex;
    }

    if (rightChildIndex < size && array[rightChildIndex] > array[smallestIndex]) {
      smallestIndex = rightChildIndex;
    }

    if (smallestIndex == i) break;

    swap(array, i, smallestIndex);
    i = smallestIndex;
  }
}

void _siftUp(List<int> array, int i, int size) {
  while (i <= 0) {
    var parentIndex = (i - 1) ~/ 2;
    if (array[parentIndex] < array[i]) {
      swap(array, parentIndex, i);
      i = parentIndex;
    } else break;
  }
}

