  final cols = grid[0].length;

  // Initialize the minimum path sum with a large value
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, double.infinity.toInt()));

  // Base case: starting at (0, 0)
  dp[0][0] = grid[0][0];

  for (int i = 0; i < rows; ++i) {
    for (int j = 0; j < cols; ++j) {
      if (i > 0) {
        dp[i][j] = min(dp[i][j], dp[i - 1][j]);
      }
      if (j > 0) {
        dp[i][j] = min(dp[i][j], dp[i][j - 1]);
      }

      // If we have reached k steps and current cell is not part of the minimal path yet
