List<int> minPath(List<List<int>> grid, int k) {
  final rows = grid.length;
  final cols = grid[0].length;

  if (rows == 0 || cols == 0) return [];

  // Directions: right and down
  final directions = <int>[1, 0];

  final dp = List.generate(rows * cols + 1, (_) => -1);
  final visited = List<bool>.filled(rows * cols + 1, false);

  void dfs(int row, int col, int steps) {
    if (steps > k) return;

    var index = row * cols + col;

    if (visited[index] && dp[index] != -1) {
      if (dp[index] >= steps) return;
      return; 
    }

    if (dp[index] == -1 || steps < dp[index]) {
      dp[index] = steps;
    }

    for (var dir in directions) {
      var newRow = row + dir;
      var newCol = col;

      if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols) {
        dfs(newRow, newCol, steps + grid[newRow][newCol]);
      }
    }

    visited[index] = true;
  }

  dfs(0, 0, grid[0][0]);

  var result = [grid[0][0]];
  var currentSteps = grid[0][0];
  var i = 0;

  while (currentSteps < k) {
    var bestStep = -1;
    var nextIndex = -1;

    for (var j = 0; j < rows * cols; ++j) {
      if (dp[j] != -1 && dp[j] <= currentSteps + 1) {
        if (bestStep == -1 || dp[j] < bestStep) {
          bestStep = dp[j];
          nextIndex = j;
        }
      }
    }

    if (nextIndex == -1) break;

    result.add(grid[nextIndex ~/ cols][nextIndex % cols]);
    currentSteps += grid[nextIndex ~/ cols][nextIndex % cols];
    i++;
  }

  return result;
}

