      // Collect alphanumeric characters to form the token
      var sb = StringBuffer();
      while (i < s.length && !s[i].isWhitespace() && s[i] != ',' && 
          s[i] != ')' && s[i] != '(' && s[i] != '{' && s[i] != '}' && s[i] != '#' && s[i] != ']') {
        sb.write(s[i]);
        i +=1;
      }
      tokens.add(sb.toString());
    }
  }

  return tokens.join(',');
}

String solve(String s) {
  final List<int> digits = [];
  for (int i=0; i < s.length && digits.length < 16; ++i) {
    if ('0' <= s[i] && s[i] <= '9') {
      int d = s.codeUnitAt(i).difference('0'.codeUnits.first);
      digits.add(d);
    }
  }

  // Convert the list of digits to a number as a string
  String result = '';
  bool firstNonZeroFound = false;
  for (final digit in digits) {
    if (digit == 0 && !firstNonZeroFound) continue;
    else if (digit != 0 || digits.isNotEmpty) {
      firstNonZeroFound = true;
      result += digit.toString();
    }
  }

  return result.isEmpty ? "0" : result;
}

String solve(String s) {
  if (s.isEmpty || s.length == 1) return 'YES';

  int n = s.length;
  List<int> arr = [];
  for(int i=0; i < n; i++) {
    arr.add(s.codeUnitAt(i));
  }

  // Check for even and odd length
  bool isEven = (n % 2 == 0);
  String result = 'NO';

  if(isEven) {

    int midIndex = n ~/ 2 - 1;
    int leftSum = getSubArraySum(arr, 0, midIndex);
    int rightSum = getSubArraySum(arr, midIndex + 1, n-1);

    if(leftSum == rightSum && areMirrorStrings(s, 0, midIndex, midIndex+1, n-1)) {
      result = 'YES';
    } else {
      result = 'NO';
    }
  } else { 
    int midIndex = n ~/ 2;
    int leftSum = getSubArraySum(arr, 0, midIndex - 1);
    int rightSum = getSubArraySum(arr, midIndex + 1, n-1);

    if(leftSum == rightSum && areMirrorStrings(s, 0, midIndex - 1, midIndex + 1, n-1)) {
      result = 'YES';
    } else {
      result = 'NO';
    }
  }

  return result;
}

int getSubArraySum(List<int> nums, int start, int end) {
  int sum = 0;
  for(int i=start; i <= end; i++) {
    sum += nums[i];
  }
  return sum;
}

bool areMirrorStrings(String s, int lStart, int rEnd, int rStart, int lEnd) {
  while(lStart <= rEnd) {
    if(s[lStart] != s[rEnd]) return false;
    lStart++;
    rEnd--;
  }
  return true;
}

